'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','warning-details.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);return {catalog:c.window.PhoenixWarningCatalog,tasks:c.window.PHOENIX_ROUTE.tasks};}
test('contextual warnings share one risk entry while unrelated timed choices stay untouched',()=>{const {catalog:c}=setup();assert.equal(c.hub('q-lilac'),'poi-4');assert.equal(c.hub('q-beast'),'poi-4');assert.equal(c.context('q-lilac','1'),'poi-4');assert.equal(c.context('q-beast','trophy'),'poi-4');assert.equal(c.context('q-lilac','4'),'departure');assert.equal(c.context('q-incident','2'),'departure');assert.equal(c.context('q-beast','payment'),null);});
test('every explanation links a real entry and supplies consequence, cutoff and prevention without changing task data',()=>{const {catalog:c,tasks}=setup(),before=JSON.stringify(tasks);for(const id of ['poi-4','departure','q-firestarter','q-missing','q-death']){const d=c.get(id,tasks);for(const f of ['title','short','consequence','cutoff','prevention','action'])assert.ok(d[f]);assert.ok(Object.values(tasks).some(t=>t.view===d.href.slice(1).split('/')[0]));}assert.equal(c.get('unknown',tasks),null);assert.equal(JSON.stringify(tasks),before);});
